impl ToLuaValue for mod_api::PlayerDataRefusal {
    fn to_lua_value(&self, lua: &Lua) -> mlua::Result<Value> {
        let table = lua.create_table()?;
        match self {
            mod_api::PlayerDataRefusal::Stale => {
                table.raw_set("tag", "stale")?;
            }
            mod_api::PlayerDataRefusal::Client => {
                table.raw_set("tag", "client")?;
            }
            mod_api::PlayerDataRefusal::Dead => {
                table.raw_set("tag", "dead")?;
            }
            mod_api::PlayerDataRefusal::SlotOutOfRange { slot, last } => {
                table.raw_set("tag", "slot_out_of_range")?;
                table.raw_set("slot", slot.to_lua_value(lua)?)?;
                table.raw_set("last", last.to_lua_value(lua)?)?;
            }
            mod_api::PlayerDataRefusal::TooDeep => {
                table.raw_set("tag", "too_deep")?;
            }
            mod_api::PlayerDataRefusal::Stack(f0) => {
                table.raw_set("tag", "stack")?;
                table.raw_set(1, f0.to_lua_value(lua)?)?;
            }
            _ => return Err(mlua::Error::runtime("unknown variant of PlayerDataRefusal")),
        }
        Ok(Value::Table(table))
    }
}

