impl ToLuaValue for mod_api::PlayerWorldRefusal {
    fn to_lua_value(&self, lua: &Lua) -> mlua::Result<Value> {
        let table = lua.create_table()?;
        match self {
            mod_api::PlayerWorldRefusal::Stale => {
                table.raw_set("tag", "stale")?;
            }
            mod_api::PlayerWorldRefusal::Client => {
                table.raw_set("tag", "client")?;
            }
            mod_api::PlayerWorldRefusal::NoConnection => {
                table.raw_set("tag", "no_connection")?;
            }
            mod_api::PlayerWorldRefusal::Dead => {
                table.raw_set("tag", "dead")?;
            }
            mod_api::PlayerWorldRefusal::NegativeSequence { sequence } => {
                table.raw_set("tag", "negative_sequence")?;
                table.raw_set("sequence", sequence.to_lua_value(lua)?)?;
            }
            mod_api::PlayerWorldRefusal::PositionNotSendable { pos } => {
                table.raw_set("tag", "position_not_sendable")?;
                table.raw_set("pos", pos.to_lua_value(lua)?)?;
            }
            mod_api::PlayerWorldRefusal::UnknownState => {
                table.raw_set("tag", "unknown_state")?;
            }
            mod_api::PlayerWorldRefusal::StaleLevel => {
                table.raw_set("tag", "stale_level")?;
            }
            mod_api::PlayerWorldRefusal::OtherLevel => {
                table.raw_set("tag", "other_level")?;
            }
            mod_api::PlayerWorldRefusal::OutOfWorld { pos } => {
                table.raw_set("tag", "out_of_world")?;
                table.raw_set("pos", pos.to_lua_value(lua)?)?;
            }
            mod_api::PlayerWorldRefusal::NotLoaded { pos } => {
                table.raw_set("tag", "not_loaded")?;
                table.raw_set("pos", pos.to_lua_value(lua)?)?;
            }
            mod_api::PlayerWorldRefusal::Unchanged => {
                table.raw_set("tag", "unchanged")?;
            }
            _ => return Err(mlua::Error::runtime("unknown variant of PlayerWorldRefusal")),
        }
        Ok(Value::Table(table))
    }
}

