impl ToLuaValue for mod_api::Pose {
    fn to_lua_value(&self, lua: &Lua) -> mlua::Result<Value> {
        let name = match self {
            mod_api::Pose::Standing => "standing",
            mod_api::Pose::FallFlying => "fall_flying",
            mod_api::Pose::Sleeping => "sleeping",
            mod_api::Pose::Swimming => "swimming",
            mod_api::Pose::SpinAttack => "spin_attack",
            mod_api::Pose::Crouching => "crouching",
            mod_api::Pose::LongJumping => "long_jumping",
            mod_api::Pose::Dying => "dying",
            mod_api::Pose::Croaking => "croaking",
            mod_api::Pose::UsingTongue => "using_tongue",
            mod_api::Pose::Sitting => "sitting",
            mod_api::Pose::Roaring => "roaring",
            mod_api::Pose::Sniffing => "sniffing",
            mod_api::Pose::Emerging => "emerging",
            mod_api::Pose::Digging => "digging",
            mod_api::Pose::Sliding => "sliding",
            mod_api::Pose::Shooting => "shooting",
            mod_api::Pose::Inhaling => "inhaling",
        };
        Ok(Value::String(lua.create_string(name)?))
    }
}

